            ld h, a		; Vox.cls 2900
            ret		; Vox.cls 2901

; ---- an edge D = xa, E = ya to B = xb, C = yb: x' for each of its rows on the screen, into
; ed_d (going down: the right side) or ed_u (going up: the left). Keeps IX
fn_vox_render_edge:		; Vox.cls 2905
            ld a, e		; Vox.cls 2906
            cp c		; Vox.cls 2907
            ret z		; Vox.cls 2908
            ld h, fn_vox_render_ed_d / 256		; Vox.cls 2909
            jr c, fn_vox_render_eg_1		; Vox.cls 2910
            ld a, d                 ; going up: the ends swapped [2911]
            ld d, b		; Vox.cls 2912
            ld b, a		; Vox.cls 2913
            ld a, e		; Vox.cls 2914
            ld e, c		; Vox.cls 2915
            ld c, a		; Vox.cls 2916
            ld h, fn_vox_render_ed_u / 256		; Vox.cls 2917
fn_vox_render_eg_1:		; Vox.cls 2918
            ; rows y0 = max(ya, 88) .. y1 = min(yb, 168)
            ld a, e		; Vox.cls 2920
            cp 88		; Vox.cls 2921
            jr nc, fn_vox_render_eg_2		; Vox.cls 2922
            ld a, 88		; Vox.cls 2923
fn_vox_render_eg_2:		; Vox.cls 2924
            ld l, a		; Vox.cls 2925
            ld a, c		; Vox.cls 2926
            cp 168		; Vox.cls 2927
            jr c, fn_vox_render_eg_3		; Vox.cls 2928
            ld a, 168		; Vox.cls 2929
fn_vox_render_eg_3:		; Vox.cls 2930
            ld (fn_vox_render_eg_end + 1), a		; Vox.cls 2931
            cp l		; Vox.cls 2932
            ret c		; Vox.cls 2933
            ret z		; Vox.cls 2934
            ld (fn_vox_render_eg_ptr), hl		; Vox.cls 2935
            ld a, l		; Vox.cls 2936
            sub e		; Vox.cls 2937
            ld (fn_vox_render_eg_k), a            ; rows skipped [2938]
            ld a, d		; Vox.cls 2939
            ld (fn_vox_render_eg_xa), a		; Vox.cls 2940
            ld a, c		; Vox.cls 2941
            sub e		; Vox.cls 2942
            ld l, a                 ; dy [2943]
            ld a, b		; Vox.cls 2944
            sub d                   ; dx [2945]
            ld c, 0		; Vox.cls 2946
            jr nc, fn_vox_render_eg_4		; Vox.cls 2947
            neg		; Vox.cls 2948
            dec c		; Vox.cls 2949
fn_vox_render_eg_4:		; Vox.cls 2950
            ; step (8.8) = |dx| * RY(dy) >> 8, RY = 65536 / dy
            ld (fn_vox_render_eg_adx), a		; Vox.cls 2952
            ld h, fn_vox_render_ry_l / 256		; Vox.cls 2953
            ld e, (hl)		; Vox.cls 2954
            inc h		; Vox.cls 2955
            ld b, (hl)		; Vox.cls 2956
            ld d, a		; Vox.cls 2957
fn_vox_render_eg_zm1:		; Vox.cls 2958
            db #ED, #30             ; mul d, e: |dx| * RY low [2959]
            ld l, d		; Vox.cls 2960
            ld a, (fn_vox_render_eg_adx)		; Vox.cls 2961
            ld d, a		; Vox.cls 2962
            ld e, b		; Vox.cls 2963
fn_vox_render_eg_zm2:		; Vox.cls 2964
            db #ED, #30             ; |dx| * RY high [2965]
            ld h, 0		; Vox.cls 2966
            add hl, de		; Vox.cls 2967
            ld a, c		; Vox.cls 2968
            or a		; Vox.cls 2969
            jr z, fn_vox_render_eg_5		; Vox.cls 2970
            xor a		; Vox.cls 2971
            sub l		; Vox.cls 2972
            ld l, a		; Vox.cls 2973
            sbc a, a		; Vox.cls 2974
            sub h		; Vox.cls 2975
            ld h, a		; Vox.cls 2976
fn_vox_render_eg_5:		; Vox.cls 2977
            ld (fn_vox_render_eg_st), hl		; Vox.cls 2978
            ; x = xa * 256 + 128 + k * step (16 bits)
            ld a, (fn_vox_render_eg_xa)		; Vox.cls 2980
            ld d, a		; Vox.cls 2981
            ld e, 128		; Vox.cls 2982
            ld a, (fn_vox_render_eg_k)		; Vox.cls 2983
            or a		; Vox.cls 2984
            jr z, fn_vox_render_eg_6		; Vox.cls 2985
            push de		; Vox.cls 2986
            ld b, a		; Vox.cls 2987
            ld d, a		; Vox.cls 2988
            ld e, l		; Vox.cls 2989
fn_vox_render_eg_zm3:		; Vox.cls 2990
            db #ED, #30             ; k * step low [2991]
            push de		; Vox.cls 2992
            ld d, b		; Vox.cls 2993
            ld e, h		; Vox.cls 2994
fn_vox_render_eg_zm4:		; Vox.cls 2995
            db #ED, #30             ; k * step high: its low byte goes in the high byte [2996]
            pop hl		; Vox.cls 2997
            ld a, h		; Vox.cls 2998
            add a, e		; Vox.cls 2999
            ld h, a		; Vox.cls 3000
            pop de		; Vox.cls 3001
            add hl, de		; Vox.cls 3002
            ex de, hl		; Vox.cls 3003
fn_vox_render_eg_6:		; Vox.cls 3004
            ex de, hl               ; HL = x (8.8) [3005]
            ld de, (fn_vox_render_eg_st)		; Vox.cls 3006
            ld bc, (fn_vox_render_eg_ptr)		; Vox.cls 3007
fn_vox_render_eg_lp:		; Vox.cls 3008
            ld a, h		; Vox.cls 3009
            ld (bc), a		; Vox.cls 3010
            inc c		; Vox.cls 3011
            add hl, de		; Vox.cls 3012
            ld a, c		; Vox.cls 3013
fn_vox_render_eg_end:		; Vox.cls 3014
            cp 0                    ; (y1: written above) [3015]
            jr nz, fn_vox_render_eg_lp		; Vox.cls 3016
            ret		; Vox.cls 3017

; ================================================================ the coverage of a row
; cover: HL = the row's list (n, then n pairs start, end - in order, apart), B = a, C = b
; (a < b): fills the parts of a .. b not filled yet this frame, and puts a .. b in the list
fn_vox_render_cover:		; Vox.cls 3022
            ld a, (hl)		; Vox.cls 3023
            or a		; Vox.cls 3024
            jr nz, fn_vox_render_cv_some		; Vox.cls 3025
            ; an empty row
            inc (hl)		; Vox.cls 3027
            inc hl		; Vox.cls 3028
            ld (hl), b		; Vox.cls 3029
            inc hl		; Vox.cls 3030
            ld (hl), c		; Vox.cls 3031
            ld a, b		; Vox.cls 3032
            or a		; Vox.cls 3033
            jp nz, fn_vox_render_fill		; Vox.cls 3034
            ld a, c		; Vox.cls 3035
            cp 96		; Vox.cls 3036
            jp nz, fn_vox_render_fill		; Vox.cls 3037
            ld hl, fn_vox_render_rd_full		; Vox.cls 3038
            inc (hl)		; Vox.cls 3039
            jp fn_vox_render_fill		; Vox.cls 3040
fn_vox_render_cv_some:		; Vox.cls 3041
            cp 1		; Vox.cls 3042
            jr nz, fn_vox_render_cv_n1		; Vox.cls 3043
            ; one pair: 0 .. 128 is a full row
            inc hl		; Vox.cls 3045
            ld a, (hl)		; Vox.cls 3046
            inc hl		; Vox.cls 3047
            or a		; Vox.cls 3048
            jr nz, fn_vox_render_cv_n0		; Vox.cls 3049
            ld a, (hl)		; Vox.cls 3050
            cp 96		; Vox.cls 3051
            ret z		; Vox.cls 3052
fn_vox_render_cv_n0:		; Vox.cls 3053
            dec hl		; Vox.cls 3054
            dec hl		; Vox.cls 3055
            ld a, 1		; Vox.cls 3056
fn_vox_render_cv_n1:		; Vox.cls 3057
            ld (fn_vox_render_cv_blk), hl		; Vox.cls 3058
            ld e, a                 ; pairs left [3059]
            inc hl		; Vox.cls 3060
fn_vox_render_cv_s1:		; Vox.cls 3061
            inc hl		; Vox.cls 3062
            ld a, (hl)              ; end(i) [3063]
            cp b		; Vox.cls 3064
            jr nc, fn_vox_render_cv_s2            ; end(i) >= a: from this one [3065]
            inc hl		; Vox.cls 3066
            dec e		; Vox.cls 3067
            jr nz, fn_vox_render_cv_s1		; Vox.cls 3068
            ; every pair ends before a: a .. b goes on the end
            ld hl, (fn_vox_render_cv_blk)		; Vox.cls 3070
            ld a, (hl)		; Vox.cls 3071
            cp 15		; Vox.cls 3072
            jp nc, fn_vox_render_fill		; Vox.cls 3073
            inc (hl)		; Vox.cls 3074
            add a, a		; Vox.cls 3075
            inc a		; Vox.cls 3076
            ld e, a		; Vox.cls 3077
            ld d, 0		; Vox.cls 3078
            add hl, de		; Vox.cls 3079
            ld (hl), b		; Vox.cls 3080
            inc hl		; Vox.cls 3081
            ld (hl), c		; Vox.cls 3082
            jp fn_vox_render_fill		; Vox.cls 3083
fn_vox_render_cv_s2:		; Vox.cls 3084
            dec hl                  ; HL = start(i), E = the pairs from i on [3085]
            ld a, (hl)		; Vox.cls 3086
            cp c		; Vox.cls 3087
            jr z, fn_vox_render_cv_ov		; Vox.cls 3088
            jr c, fn_vox_render_cv_ov		; Vox.cls 3089
            ; start(i) > b: a .. b goes in before it
            push hl		; Vox.cls 3091
            ld hl, (fn_vox_render_cv_blk)		; Vox.cls 3092
            ld a, (hl)		; Vox.cls 3093
            cp 15		; Vox.cls 3094
            jr nc, fn_vox_render_cv_i0		; Vox.cls 3095
            inc (hl)		; Vox.cls 3096
            pop hl		; Vox.cls 3097
            push bc		; Vox.cls 3098
            ld a, e		; Vox.cls 3099
            add a, a		; Vox.cls 3100
            ld c, a		; Vox.cls 3101
            ld b, 0		; Vox.cls 3102
            add hl, bc		; Vox.cls 3103
            dec hl		; Vox.cls 3104
            ld d, h		; Vox.cls 3105
            ld e, l		; Vox.cls 3106
            inc de		; Vox.cls 3107
            inc de		; Vox.cls 3108
            lddr		; Vox.cls 3109
            inc hl		; Vox.cls 3110
            pop bc		; Vox.cls 3111
            ld (hl), b		; Vox.cls 3112
            inc hl		; Vox.cls 3113
            ld (hl), c		; Vox.cls 3114
            jp fn_vox_render_fill		; Vox.cls 3115
fn_vox_render_cv_i0:		; Vox.cls 3116
            pop hl		; Vox.cls 3117
            jp fn_vox_render_fill		; Vox.cls 3118
; ---- fill: B .. C (B < C) of the row at fl_h, colour fl_col: two Layer 2 lines, by PUSH
fn_vox_render_fill:		; Vox.cls 3120
            ld a, c		; Vox.cls 3121
            sub b		; Vox.cls 3122
            ld e, a		; Vox.cls 3123
            ld d, 0		; Vox.cls 3124
            ld hl, fn_vox_render_pf_end		; Vox.cls 3125
            sbc hl, de		; Vox.cls 3126
            ld (fn_vox_render_fl_j1 + 1), hl		; Vox.cls 3127
            ld (fn_vox_render_fl_j2 + 1), hl		; Vox.cls 3128
            ld a, (fn_vox_render_fl_h)		; Vox.cls 3129
            ld h, a		; Vox.cls 3130
            ld a, c		; Vox.cls 3131
            add a, a		; Vox.cls 3132
            ld l, a		; Vox.cls 3133
            jr nc, fn_vox_render_fl_1		; Vox.cls 3134
            inc h		; Vox.cls 3135
fn_vox_render_fl_1:		; Vox.cls 3136
            ld de, (fn_vox_render_fl_col)		; Vox.cls 3137
            ld (fn_vox_render_fl_sp), sp		; Vox.cls 3138
            ld ix, fn_vox_render_fl_r1		; Vox.cls 3139
            db #F9                  ; ld sp, hl (as a byte: NTC takes a "ld sp, hl" for a branch) [3140]
fn_vox_render_fl_j1:		; Vox.cls 3141
            jp 0		; Vox.cls 3142
fn_vox_render_fl_r1:		; Vox.cls 3143
            inc h		; Vox.cls 3144
            db #F9                  ; ld sp, hl [3145]
            ld ix, fn_vox_render_fl_r2		; Vox.cls 3146
fn_vox_render_fl_j2:		; Vox.cls 3147
            jp 0		; Vox.cls 3148
fn_vox_render_fl_r2:		; Vox.cls 3149
            ld sp, (fn_vox_render_fl_sp)		; Vox.cls 3150
            ret		; Vox.cls 3151
fn_vox_render_cv_ov:		; Vox.cls 3152
            ; it meets pair i: merge from there. ns = min(a, start(i)), D = filled up to
            ld (fn_vox_render_cv_ip), hl		; Vox.cls 3154
            cp b		; Vox.cls 3155
            jr c, fn_vox_render_cv_o1		; Vox.cls 3156
            ld a, b		; Vox.cls 3157
fn_vox_render_cv_o1:		; Vox.cls 3158
            ld (fn_vox_render_cv_ns), a		; Vox.cls 3159
            ld d, b		; Vox.cls 3160
fn_vox_render_cv_m:		; Vox.cls 3161
            ld a, (hl)              ; start(j) [3162]
            cp d		; Vox.cls 3163
            jr z, fn_vox_render_cv_m1		; Vox.cls 3164
            jr c, fn_vox_render_cv_m1		; Vox.cls 3165
            push bc		; Vox.cls 3166
            push de		; Vox.cls 3167
            push hl		; Vox.cls 3168
            ld c, a		; Vox.cls 3169
            ld b, d		; Vox.cls 3170
            call fn_vox_render_fill               ; the gap before it [3171]
            pop hl		; Vox.cls 3172
            pop de		; Vox.cls 3173
            pop bc		; Vox.cls 3174
fn_vox_render_cv_m1:		; Vox.cls 3175
            inc hl		; Vox.cls 3176
            ld a, (hl)              ; end(j) [3177]
            cp d		; Vox.cls 3178
            jr c, fn_vox_render_cv_m2		; Vox.cls 3179
            ld d, a		; Vox.cls 3180
fn_vox_render_cv_m2:		; Vox.cls 3181
            inc hl		; Vox.cls 3182
            dec e		; Vox.cls 3183
            jr z, fn_vox_render_cv_m3		; Vox.cls 3184
            ld a, (hl)		; Vox.cls 3185
            cp c		; Vox.cls 3186
            jr z, fn_vox_render_cv_m		; Vox.cls 3187
            jr c, fn_vox_render_cv_m		; Vox.cls 3188
fn_vox_render_cv_m3:		; Vox.cls 3189
            ; the rest: D .. b
            ld a, d		; Vox.cls 3191
            cp c		; Vox.cls 3192
            jr nc, fn_vox_render_cv_m4		; Vox.cls 3193
            push de		; Vox.cls 3194
            push hl		; Vox.cls 3195
            ld b, d		; Vox.cls 3196
            call fn_vox_render_fill		; Vox.cls 3197
            pop hl		; Vox.cls 3198
            pop de		; Vox.cls 3199
            ld d, c		; Vox.cls 3200
fn_vox_render_cv_m4:		; Vox.cls 3201
            ; the merged pairs become ns .. D; E pairs after them (from HL) move down
            push hl		; Vox.cls 3203
            ld hl, (fn_vox_render_cv_ip)		; Vox.cls 3204
            ld a, (fn_vox_render_cv_ns)		; Vox.cls 3205
            ld (hl), a		; Vox.cls 3206
            inc hl		; Vox.cls 3207
            ld (hl), d		; Vox.cls 3208
            inc hl		; Vox.cls 3209
            pop bc		; Vox.cls 3210
            ld a, c		; Vox.cls 3211
            sub l		; Vox.cls 3212
            jr z, fn_vox_render_cv_m6             ; one pair merged: nothing moves [3213]
            rrca		; Vox.cls 3214
            ld d, a                 ; pairs gone [3215]
            ld a, e		; Vox.cls 3216
            or a		; Vox.cls 3217
            jr z, fn_vox_render_cv_m5		; Vox.cls 3218
            push de		; Vox.cls 3219
            ex de, hl		; Vox.cls 3220
            ld h, b		; Vox.cls 3221
            ld l, c		; Vox.cls 3222
            add a, a		; Vox.cls 3223
            ld c, a		; Vox.cls 3224
            ld b, 0		; Vox.cls 3225
            ldir		; Vox.cls 3226
            pop de		; Vox.cls 3227
fn_vox_render_cv_m5:		; Vox.cls 3228
            ld hl, (fn_vox_render_cv_blk)		; Vox.cls 3229
            ld a, (hl)		; Vox.cls 3230
            sub d		; Vox.cls 3231
            ld (hl), a		; Vox.cls 3232
fn_vox_render_cv_m6:		; Vox.cls 3233
            ; full now?
            ld hl, (fn_vox_render_cv_blk)		; Vox.cls 3235
            ld a, (hl)		; Vox.cls 3236
            dec a		; Vox.cls 3237
            ret nz		; Vox.cls 3238
            inc hl		; Vox.cls 3239
            ld a, (hl)		; Vox.cls 3240
            or a		; Vox.cls 3241
            ret nz		; Vox.cls 3242
            inc hl		; Vox.cls 3243
            ld a, (hl)		; Vox.cls 3244
            cp 96		; Vox.cls 3245
            ret nz		; Vox.cls 3246
            ld hl, fn_vox_render_rd_full		; Vox.cls 3247
            inc (hl)		; Vox.cls 3248
            ret		; Vox.cls 3249

; ---- the sky in what's left, row by row (and the lists emptied for the next frame)
fn_vox_render_rd_sky:		; Vox.cls 3252
            xor a		; Vox.cls 3253
fn_vox_render_sk_lp:		; Vox.cls 3254
            ld (fn_vox_render_sk_r), a		; Vox.cls 3255
